const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const state={route:'overview',settlements:initialSettlements.map(s=>({...s})),beneficiaries:initialBeneficiaries.map(s=>({...s})),batches:initialBatches.map(b=>({...b})),selected:'STL-784521',checked:new Set(),filters:{query:'',status:'',corridor:'',currency:'',start:'2024-06-01',end:'2024-06-30'},sort:'desc',page:1,cpQuery:'',reconcileTab:'transactions',settingsTab:'profile',profile:{name:'Rohit Mehta',email:'rohit@acme.example',company:'Acme Global Pvt Ltd',country:'India',timezone:'Asia/Kolkata',role:'Administrator'},preferences:{email:true,settlements:true,availability:true,weekly:false},wizard:null,notificationsRead:false,pendingDetail:null,canSettleNow:true,availableToSettle:48200000,treasury:{reserve:2500000,target:4000000,auto:true},organisation:{country:'India',type:'Private Limited Company',address:'Bandra Kurla Complex, Mumbai, Maharashtra, India'}};
const PAGE_SIZE=8;
const status=s=>`<span class="status ${s.toLowerCase().replaceAll(' ','-')}">${esc(s)}</span>`;
const btn=(label,action,ico='',kind='',attrs='')=>`<button class="btn ${kind}" ${attrs.includes('type=')?'':'type="button"'} data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const smallButton=(label,action,attrs='')=>`<button class="small-button" data-action="${action}" ${attrs}>${label}</button>`;
const panelHead=(title,action='',right='')=>`<div class="panel-head"><h2>${title}${action?`<button class="circle-link" data-action="${action}" aria-label="Open ${title}">${icon('chevron-right')}</button>`:''}</h2>${right}</div>`;
const heading=(title,subtitle)=>`<header class="page-heading"><p class="greeting">Good morning, ${esc(state.profile.name.split(' ')[0])}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></header>`;
// DESIGN_SYSTEM.md § 5: "Label, value, and one line of context." A delta chip
// is permitted only where acting on the delta is the point, and none of the
// four § 12.1 metrics has one — so `context` replaces `change`/`note` and the
// chip renders only when a caller genuinely passes a delta.
function metrics(items){return `<div class="metrics">${items.map(m=>`<article class="metric ${m.compact?'compact':''}"><span class="metric-icon">${icon(m.icon)}</span><div class="metric-content"><span class="metric-label">${m.label}</span><div class="metric-numbers"><strong class="metric-value">${m.value}</strong><span class="${['metric-change',m.context&&'metric-context',m.negative&&'negative'].filter(Boolean).join(' ')}">${m.change??''}<small>${m.context??m.note??''}</small></span></div>${m.action?`<button class="small-button metric-action" data-action="${m.action.action}">${m.action.label}</button>`:''}</div></article>`).join('')}</div>`;}
function distribution(){return `<div class="liquidity-distribution"><div class="balance-track" aria-label="Liquidity distribution: USDC 48%, USDT 32%, EURC 12%, other 8%">${balances.map(b=>`<span style="width:${b.share}%;background:${b.color}"></span>`).join('')}</div><div class="balance-legend">${balances.map((b,i)=>`<span>${i===3?'Others':b.currency} <b>${b.share}%</b></span>`).join('')}</div></div>`;}
function featuredCorridor(){return `<section class="panel featured-corridor">${panelHead('Featured Corridor','corridors',status('Live'))}<div class="corridor-summary"><div><h3>INR <span>→</span> USDC</h3><p>Rupee to Global Opportunity</p></div><div><small>Typical settlement time</small><strong>&lt; 60s</strong></div></div><div class="corridor-flow"><div class="flow-end"><span class="currency-large inr">${rupeeMark()}</span><strong>INR</strong><small>Local Collection<br>(NPCI / Bank Transfer)</small></div><div class="flow-center"><div class="flow-brand"><img src="/assets/brand-wordmark.svg" width="934" height="95" alt="INRSettle"></div><small>Compliance &nbsp;·&nbsp; Liquidity &nbsp;·&nbsp; Settlement</small></div><div class="flow-end"><span class="currency-large usdc">${coin('USDC')}</span><strong>USDC</strong><small>Global Payout<br>(Multi-chain)</small></div></div></section>`;}
function recentTable(){return `<section class="panel recent-panel">${panelHead('Recent Settlements','settlements',smallButton('View All','settlements'))}<div class="table-scroll"><table class="data-table recent-table"><thead><tr><th>ID</th><th>Date &amp; Time</th><th>Corridor</th><th>Amount</th><th>Status</th><th class="actions-cell">Actions</th></tr></thead><tbody>${state.settlements.slice(0,5).map(s=>`<tr data-row="${s.id}"><td><button class="row-link" data-action="open-settlement" data-id="${s.id}">${s.id}</button></td><td class="date-cell muted">${displayDate(s.date)} ${s.time}</td><td>${pair(s)}</td><td>${money(s.send,s.from)}<span class="value-secondary">${money(s.receive,s.to)}</span></td><td>${status(s.status)}</td><td class="actions-cell"><button class="row-more" data-action="row-actions" data-id="${s.id}" aria-label="Actions for ${s.id}">···</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function liquidity(){return `${heading('Liquidity & Treasury','Keep capital ready. Monitor balances, allocation and liquidity across your corridors.')}<div class="page-actions"><span class="environment-pill">Treasury overview</span>${btn('Rebalance','rebalance','arrow-right-left')}${btn('Add Liquidity','add-liquidity','plus','primary')}</div><div class="balance-grid">${balances.map(b=>`<article class="panel balance-card"><div class="balance-top">${coin(b.currency)}<strong>${b.currency}</strong>${status('Available')}</div><strong>$ ${(b.amount/1e6).toFixed(2)}M</strong><span class="balance-unit">USD equivalent</span><p>${b.network}</p><div class="balance-track"><span style="width:${b.share*1.6}%;background:${b.color}"></span></div><small>${b.share}% of total liquidity <span class="positive">&nbsp; ${b.change}</span></small></article>`).join('')}</div><div class="secondary-grid"><section class="panel">${panelHead('Available Liquidity','',smallButton('Download','liquidity-report'))}<div class="liquidity-summary"><div class="liquidity-available"><small>Total balance · USD equivalent</small><strong>$ 12,400,000</strong></div>${distribution()}</div><div class="balance-chart"><div class="chart-scale"><span>$15M</span><span>$10M</span><span>$5M</span><span>$0</span></div><div class="bars-chart">${[8.1,8.7,10.2,9.4,11.7,10.8,12.4].map((v,i)=>`<button class="balance-bar ${i===6?'active':''}" style="height:${v/15*100}%" data-action="chart-day" aria-label="June ${18+i}, liquidity ${v} million dollars"><b>$${v}M</b><span>Jun ${18+i}</span></button>`).join('')}</div></div></section><section class="panel">${panelHead('Treasury Controls')}<ul class="key-value-list"><li><span>Auto top-up<small>Replenish before balances run low</small></span><label aria-label="Enable automatic top-up"><input class="switch" type="checkbox" data-preference="topup" ${state.treasury.auto?'checked':''}></label></li><li><span>Minimum reserve<small>Across active settlement corridors</small></span><span class="value">$ ${(state.treasury.reserve/1e6).toFixed(1)}M</span></li><li><span>Next replenishment<small>Estimated settlement window</small></span><span class="value">3–6 hours<small class="positive">On schedule</small></span></li><li><span>Capital in settlement</span><span class="value">$ 842,000</span></li></ul><div class="card-footer">${btn('Manage treasury rules','treasury-rules','settings')}</div></section></div><section class="panel wide-panel">${panelHead('Recent Treasury Activity')}<div class="table-scroll"><table class="data-table"><thead><tr><th>Activity</th><th>Asset</th><th>Amount</th><th>Account</th><th>Date &amp; Time</th><th>Status</th></tr></thead><tbody>${[['Liquidity replenishment','USDC','$ 450,000','Primary treasury','Jun 24, 2024 · 09:30','Completed'],['Settlement reserve','USDT','$ 125,800','Singapore corridor','Jun 24, 2024 · 09:12','Reserved'],['Balance rebalance','EURC','€ 210,000','European treasury','Jun 23, 2024 · 16:40','Completed']].map(a=>`<tr><td>${a[0]}</td><td>${coin(a[1])} ${a[1]}</td><td>${a[2]}</td><td class="muted">${a[3]}</td><td class="muted">${a[4]}</td><td>${status(a[5])}</td></tr>`).join('')}</tbody></table></div></section>`;}
function reconciliation(){const settled=state.settlements.filter(s=>s.status==='Settled');return `${heading('Reconciliation & Audit','One complete record. Reconcile settlements, confirm balances and keep your audit trail clear.')}<div class="panel reconcile-banner"><span class="metric-icon">${icon('check-circle')}</span><div><h2>Everything is accounted for.</h2><p>All completed settlements are matched across on-chain and fiat rails.</p></div>${btn('Download Summary','reconciliation-report','download')}</div><div class="tabs" role="tablist" aria-label="Reconciliation views">${[['transactions','Transactions'],['reports','Reports'],['audit','Audit Trail']].map(([id,name])=>`<button role="tab" id="tab-${id}" aria-controls="reconcile-content" aria-selected="${state.reconcileTab===id}" tabindex="${state.reconcileTab===id?0:-1}" class="${state.reconcileTab===id?'active':''}" data-action="reconcile-tab" data-tab="${id}">${name}</button>`).join('')}</div><section class="panel" id="reconcile-content" role="tabpanel" aria-labelledby="tab-${state.reconcileTab}">${state.reconcileTab==='transactions'?`${panelHead('Matched Settlements','',`<span class="status">100% reconciled</span>`)}<div class="table-scroll"><table class="data-table reconcile-table"><thead><tr><th>Settlement</th><th>Beneficiary</th><th>Amount</th><th>Fiat Rails</th><th>On-chain</th><th>Reconciled</th><th>Report</th></tr></thead><tbody>${settled.map(s=>`<tr><td><button class="row-link" data-action="open-settlement" data-id="${s.id}">${s.id}</button></td><td>${esc(s.name)}</td><td>${money(s.send,s.from)}</td><td><span class="match-value">${icon('check-circle')}Matched</span></td><td>${[s.from,s.to].some(c=>['USDC','USDT','EURC'].includes(c))?`<span class="match-value">${icon('check-circle')}Matched</span>`:'<span class="muted">Not applicable</span>'}</td><td class="muted">${displayDate(s.date)}</td><td><button class="icon-button" data-action="download-report" data-id="${s.id}" aria-label="Download report for ${s.id}">${icon('download')}</button></td></tr>`).join('')}</tbody></table></div><div class="table-pagination">${settled.length} reconciled settlements<span>Zero exceptions</span></div>`:state.reconcileTab==='reports'?`${panelHead('Your Reports')}${[['Monthly Settlement Summary','All settlements, corridors and reconciliation status','June 2024'],['Treasury & Liquidity Report','Balances and asset allocation across your treasury','June 2024'],['Audit Trail Export','Settlement events and verification activity','June 2024']].map(([name,sub,date],i)=>`<div class="report-card"><span class="metric-icon">${icon('file')}</span><div><h3>${name}</h3><p>${sub}<br>${date} · CSV</p></div>${btn('Download',['all-settlements-report','liquidity-report','audit-report'][i],'download')}</div>`).join('')}`:`${panelHead('Activity Log')}${[['Settlement reconciled','STL-784521 · TechFlow Inc.','Jun 24, 2024 · 11:02'],['Settlement executed','STL-784521 · INR → USDC','Jun 24, 2024 · 11:01'],['Liquidity reserved','STL-784521 · ₹ 25,00,000','Jun 24, 2024 · 10:26'],['Compliance checks completed','TechFlow Inc. · KYC / AML cleared','Jun 24, 2024 · 10:25'],['Settlement created','STL-784521 · Created by Rohit Mehta','Jun 24, 2024 · 10:24']].map(([title,sub,time])=>`<div class="report-card"><span class="metric-icon">${icon('check-circle')}</span><div><h3>${title}</h3><p>${sub}</p></div><small class="muted" style="margin-left:auto">${time}</small></div>`).join('')}`}</section>`;}
function liquidityForm(mode){const transfer=mode==='rebalance';openDialog(`<h2 id="dialog-title">${transfer?'Rebalance Liquidity':'Add Liquidity'}</h2><p class="dialog-description">${transfer?'Preview an allocation between your treasury assets.':'Prepare a treasury replenishment in your demo workspace.'}</p><form id="liquidity-form" data-mode="${mode}"><div class="form-grid"><label class="field">${transfer?'From asset':'Asset'}<select name="asset">${balances.map(b=>`<option>${b.currency}</option>`).join('')}</select></label><label class="field">${transfer?'To asset':'Funding source'}<select name="destination">${transfer?['USDT','USDC','EURC','INR'].map(c=>`<option>${c}</option>`).join(''):'<option>Primary bank account</option><option>External treasury wallet</option>'}</select></label><label class="field full">Amount (USD equivalent)<input type="number" name="amount" min="100" max="5952000" step="0.01" value="100000" required></label></div><p class="form-error" id="liquidity-error" role="alert"></p><div class="form-actions">${btn('Cancel','dialog-close','','','type="button"')}${btn('Preview Allocation','submit-form','arrow','primary','type="submit"')}</div></form><p class="dialog-note">This is an allocation preview. Balances and funds remain unchanged.</p>`);}
function showTreasuryRules(){openDialog(`<h2 id="dialog-title">Treasury Rules</h2><p class="dialog-description">Set reserve thresholds for the demo workspace.</p><form id="treasury-form"><div class="form-grid"><label class="field">Minimum reserve (USD)<input name="reserve" type="number" value="${state.treasury.reserve}" min="10000" max="12400000" step="1000" required></label><label class="field">Replenishment target (USD)<input name="target" type="number" value="${state.treasury.target}" min="10000" max="12400000" step="1000" required></label></div><label class="switch-row"><span>Automatic replenishment<small>Show an alert when available funds fall below reserve.</small></span><input class="switch" type="checkbox" name="auto" ${state.treasury.auto?'checked':''}></label><p class="form-error" id="treasury-error" role="alert"></p><div class="form-actions">${btn('Save Demo Rules','submit-form','check','primary','type="submit"')}</div></form>`);}
function overview(){return `${heading('Global Settlement Overview','Move value across borders with confidence. Real liquidity. Real settlements. A stronger India.')}${metrics([{icon:'chart',label:'Total Settlement Volume',value:'$ 248.4M',change:'↑ +12%',note:'vs last month'},{icon:'globe',label:'Active Corridors',value:'52',change:'↑ +4',note:'Live corridors'},{icon:'shield',label:'Success Rate',value:'99.9%',change:'↑ +0.2%',note:'Last 30 days'},{icon:'clock',label:'Avg. Settlement Time',value:'48s',change:'↓ −62%',note:'vs industry average'}])}<div class="overview-grid"><div class="overview-left">${featuredCorridor()}${recentTable()}</div><div class="overview-right"><section class="panel quick-panel">${panelHead('Quick Actions','create')}<div class="quick-grid">${[['Create Settlement','Move value globally','send','create','primary'],['Add Beneficiary','Save counterparty','user-plus','add-beneficiary',''],['Run Preflight','Check before you send','file-check','preflight',''],['Track Finality','Live settlement status','activity','track','']].map(([title,sub,ico,action,cls])=>`<button class="quick-action ${cls}" data-action="${action}">${icon(ico)}<span><strong>${title}</strong><small>${sub}</small></span></button>`).join('')}</div></section><section class="panel liquidity-overview">${panelHead('Liquidity & Treasury','liquidity',smallButton('View Details','liquidity'))}<div class="liquidity-summary"><div class="liquidity-available"><small>Available Liquidity</small><strong>$ 12.4M</strong></div>${distribution()}</div><div class="replenishment"><span class="metric-icon">${icon('clock')}</span><div><small>Estimated Replenishment</small><strong>3–6 hours</strong></div><div class="auto-topup">Auto top-up<span>${state.treasury.auto?'Enabled':'Paused'}</span></div></div></section><section class="panel reconciliation-overview">${panelHead('Reconciliation & Audit','reconciliation',smallButton('View Reports','reports'))}<div class="audit-summary"><span class="metric-icon">${icon('file')}</span><div><h3>All clear</h3><p>Your settlements are in sync</p></div></div><ul class="audit-list"><li>${icon('check-circle')}On-chain reconciliation<span>100% matched</span></li><li>${icon('check-circle')}Fiat rails reconciliation<span>100% matched</span></li><li>${icon('check-circle')}Regulatory records<span>Up to date</span></li></ul></section></div></div>`;}

const dateLabel=()=>state.filters.start==='2024-06-01'&&state.filters.end==='2024-06-30'?'Jun 1, 2024 – Jun 30, 2024':!state.filters.start&&!state.filters.end?'All dates':`${state.filters.start?displayDate(state.filters.start):'Start'} – ${state.filters.end?displayDate(state.filters.end):'Today'}`;
function settlements(){return `${heading('Settlements','Track, manage and route cross-border settlements across India corridors.')}<div class="filter-toolbar"><div class="toolbar-filters"><label class="search-field">${icon('search')}<input id="settlement-search" aria-label="Search settlements" placeholder="Search by ID, beneficiary or reference…" value="${esc(state.filters.query)}" autocomplete="off"></label><select id="status-filter" aria-label="Filter by status"><option value="">All Status</option>${STATUSES.map(v=>`<option ${state.filters.status===v?'selected':''}>${v}</option>`).join('')}</select><select id="corridor-filter" aria-label="Filter by corridor"><option value="">All Corridors</option>${[...new Set(state.settlements.map(s=>s.from+'-'+s.to))].map(v=>`<option value="${v}" ${state.filters.corridor===v?'selected':''}>${v.replace('-', ' → ')}</option>`).join('')}</select><select id="currency-filter" aria-label="Filter by currency"><option value="">All Currencies</option>${['INR','USDC','USDT','EURC','AED','USD'].map(v=>`<option ${state.filters.currency===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="toolbar-commands">${btn(esc(dateLabel()),'date-range','calendar','date-filter')}${btn('Export','export','download')}${btn('Create Settlement','create','plus','primary')}</div></div><div class="settlements-layout ${state.selected?'':'no-detail'}"><section class="panel settlement-table-panel" id="settlement-results">${settlementResults()}</section><div id="settlement-details">${state.selected?details(state.settlements.find(s=>s.id===state.selected)):''}</div></div>`;}
function filteredRows(){return filterSettlements(state.settlements,state.filters).sort((a,b)=>(state.sort==='desc'?-1:1)*(a.date.localeCompare(b.date)||a.time.localeCompare(b.time)));}
function settlementResults(){
  const filtered=filteredRows();
  const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));
  state.page=Math.min(state.page,pages);
  const rows=filtered.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);
  return `${panelHead(`Settlements <span class="count-pill">${filtered.length}</span>`,``,state.checked.size?`<div class="bulk-actions"><span>${state.checked.size} selected</span>${smallButton('Export selected','export')}${smallButton('Clear','clear-selection')}</div>`:'')}
    <div class="table-scroll" tabindex="0" role="region" aria-label="Settlement records"><table class="data-table settlement-table">
    <colgroup><col class="col-check"><col class="col-id"><col class="col-corridor"><col class="col-beneficiary"><col class="col-amount"><col class="col-status"><col class="col-actions"></colgroup>
    <thead><tr><th><input type="checkbox" id="select-all" aria-label="Select settlements on this page" ${rows.length&&rows.every(s=>state.checked.has(s.id))?'checked':''}></th><th aria-sort="${state.sort==='desc'?'descending':'ascending'}"><button class="sort-button" data-action="sort" aria-label="Sort by creation date">Settlement ${icon('sort')}</button></th><th>Corridor</th><th>Beneficiary</th><th class="amount-cell">Amount</th><th>Status</th><th><span class="visually-hidden">Actions</span></th></tr></thead>
    <tbody>${rows.map(s=>`<tr data-row="${s.id}" class="${state.selected===s.id?'selected':''}" ${state.selected===s.id?'aria-current="true"':''}>
      <td><input type="checkbox" class="row-checkbox" data-id="${s.id}" aria-label="Select ${s.id}" ${state.checked.has(s.id)?'checked':''}></td>
      <td><button class="row-link" data-action="select-settlement" data-id="${s.id}">${s.id}</button><span class="row-secondary">${displayDate(s.date).replace(', 2024','')} · ${s.time}</span></td>
      <td>${pair(s)}</td><td class="beneficiary-cell"><span class="cell-primary" >${esc(s.name)}</span><span class="row-secondary">${esc(s.country==='United Arab Emirates'?'UAE':s.country)}</span></td>
      <td class="amount-cell"><span class="cell-primary">${money(s.send,s.from)}</span><span class="row-secondary receive-value">→ ${money(s.receive,s.to)}</span></td>
      <td class="status-cell">${status(s.status)}<span class="row-secondary">${s.completed?`${s.status==='Settled'?'Completed':'Last update'} ${s.completed}`:esc(s.eta||'Not submitted')}</span></td>
      <td><button class="row-more" data-action="row-actions" data-id="${s.id}" aria-label="Actions for ${s.id}" aria-haspopup="dialog">···</button></td></tr>`).join('')}
    </tbody></table>${!rows.length?`<div class="empty-state">${icon('search')}<strong>No settlements found</strong><p>Try another beneficiary, status or date range.</p>${btn('Clear Filters','clear-filters','refresh')}</div>`:''}</div>
    <div class="table-pagination"><span aria-live="polite">${rows.length?`Showing ${(state.page-1)*PAGE_SIZE+1}–${Math.min(state.page*PAGE_SIZE,filtered.length)} of ${filtered.length} settlements`:'No matching settlements'}</span><div class="pagination-controls"><button data-action="page-prev" ${state.page===1?'disabled':''} aria-label="Previous page">${icon('chevron-left')}</button>${Array.from({length:pages},(_,i)=>`<button class="${state.page===i+1?'active':''}" data-action="page" data-page="${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-action="page-next" ${state.page===pages?'disabled':''} aria-label="Next page">${icon('chevron-right')}</button></div></div>`;
}
function details(s){return settlementDetail(s,{icon,status,btn});}

function beneficiaries(){return `${heading('Beneficiaries','Your global network, connected. Manage beneficiaries and business relationships.')}${metrics([{icon:'users',label:'Total Beneficiaries',value:state.beneficiaries.length,context:'In your directory.'},{icon:'shield',label:'Verified',value:state.beneficiaries.filter(c=>c.status==='Verified').length,context:'Ready to settle.'},{icon:'globe',label:'Countries',value:new Set(state.beneficiaries.map(c=>c.country)).size,context:'Where your beneficiaries are.'},{icon:'file-check',label:'Needs Review',value:state.beneficiaries.filter(c=>c.status!=='Verified').length,context:'Waiting on a check before you can settle to them.'}])}<div class="page-actions"><label class="search-field">${icon('search')}<input id="beneficiary-search" placeholder="Search by name, country or currency…" aria-label="Search beneficiaries" value="${esc(state.cpQuery)}"></label>${btn('Export','export-beneficiaries','download')}${btn('Add Beneficiary','add-beneficiary','user-plus','primary')}</div><section class="panel" id="beneficiary-results">${beneficiaryResults()}</section>`;}
function beneficiaryResults(){const rows=state.beneficiaries.filter(c=>[c.name,c.country,c.currency,c.email].join(' ').toLowerCase().includes(state.cpQuery.toLowerCase()));return `${panelHead(`Business Network <span class="count-pill">${rows.length}</span>`)}<div class="table-scroll"><table class="data-table cp-table"><thead><tr><th>Beneficiary</th><th>Country</th><th>Currency</th><th>Verification</th><th>Contact</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>`<tr><td><button class="row-link cp-name" data-action="beneficiary" data-id="${c.id}"><span class="company-avatar">${esc(c.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><span><strong>${esc(c.name)}</strong><span class="row-secondary">${c.id}</span></span></button></td><td>${esc(c.country)}</td><td>${coin(c.currency)} ${c.currency}</td><td>${status(c.status)}</td><td class="muted">${esc(c.email)}</td><td>${smallButton('View Details','beneficiary',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div>${!rows.length?`<div class="empty-state">${icon('users')}<strong>No beneficiaries found</strong><p>Try a different company name or country.</p></div>`:''}<div class="table-pagination">Showing ${rows.length} beneficiaries<span>${esc(state.profile.company)}</span></div>`;}
const apiExample=`// Illustrative integration — no request is sent\nconst settlement = {\n  source_currency: "INR",\n  destination_currency: "USDC",\n  amount: 2500000,\n  beneficiary_id: "CP-1001",\n  reference: "TFI-2024-0624",\n  mode: "sandbox"\n};\n\n// 1. Run preflight checks\n// 2. Reserve liquidity\n// 3. Create a settlement\n// 4. Track finality via webhooks`;
// PRODUCT.md § 10 — "A batch is many independent settlements that happen to
// have been created together. It is not a transaction." The row shows the
// aggregate and the states inside it; nothing here implies the batch has a
// lifecycle of its own, because it does not. Built from the primitives the
// other screens already use, so it introduces no class without a rule.
function batches(){
  return `${heading('Batches','Many settlements created together. Each one keeps its own lifecycle.')}<div class="page-actions">${btn('Import CSV','import-batch','download')}${btn('New settlement','create','plus','primary')}</div><section class="panel" id="batch-results">${panelHead(`Batches <span class="count-pill">${state.batches.length}</span>`)}<div class="table-scroll"><table class="data-table"><thead><tr><th>Batch</th><th>Settlements</th><th>Total</th><th>Inside the batch</th><th>Created</th></tr></thead><tbody>${state.batches.map(b=>`<tr><td><span class="cell-primary">${esc(b.name)}</span><span class="value-secondary">${b.id} · ${esc(b.source)}</span></td><td>${b.count}</td><td>${money(b.total,'INR')}</td><td>${batchStatus(b).map(x=>`${x.count} ${status(x.status)}`).join(' ')}</td><td class="muted">${displayDate(b.created)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function developers(){return `${heading('Developer Workspace','Build with clarity. Explore settlement objects, events and the integration flow.')}<div class="developer-head"><span class="environment-pill">Sandbox environment</span>${btn('Explore Settlement Flow','preflight','code','primary')}</div><div class="secondary-grid"><section class="panel code-panel">${panelHead('Create a Settlement','',smallButton('Copy example','copy-api'))}<div class="code-toolbar"><span><span class="method">POST</span>/v1/settlements</span><span>Illustrative API</span></div><pre class="code-block"><code>${esc(apiExample).replace(/&quot;([^\n]*?)&quot;/g,'<span class="token-string">&quot;$1&quot;</span>')}</code></pre><p class="code-caption">Explore the object structure in this visual demo. Production endpoints and credentials are not connected.</p></section><section class="panel">${panelHead('Your Integration Path')}${[['Configure your workspace','Choose source currencies, payout currencies and settlement corridors.'],['Run a preflight','Preview compliance, routing and liquidity checks before settlement.'],['Track every event','Connect settlement progress with your operational workflow.'],['Reconcile automatically','Keep a unified record across fiat rails and on-chain transfers.']].map(([title,sub],i)=>`<div class="integration-step"><span class="step-index">0${i+1}</span><div><strong>${title}</strong><p>${sub}</p></div></div>`).join('')}</section></div><section class="panel wide-panel">${panelHead('Webhook Events','',smallButton('Preview payload','webhook'))}<div class="table-scroll"><table class="data-table"><thead><tr><th>Event</th><th>Description</th><th>Sample Delivery</th><th>Payload</th></tr></thead><tbody>${[['settlement.created','A settlement has been initiated'],['compliance.cleared','Preflight verification is complete'],['liquidity.reserved','Funds are reserved for settlement'],['settlement.completed','Funds have reached the beneficiary']].map(([name,description])=>`<tr><td><code>${name}</code></td><td class="muted">${description}</td><td>${status('Delivered')}</td><td>${smallButton('View JSON','webhook',`data-event="${name}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function settings(){return `${heading('Workspace Settings','Manage your profile, organisation and notification preferences.')}<div class="settings-layout"><nav class="panel settings-nav" aria-label="Settings categories">${[['profile','My Profile','user'],['organisation','Organisation','building'],['notifications','Notifications','bell'],['security','Security','shield']].map(([id,label,ico])=>`<button class="${state.settingsTab===id?'active':''}" data-action="settings-tab" data-tab="${id}" ${state.settingsTab===id?'aria-current="page"':''}>${icon(ico)}${label}</button>`).join('')}</nav><section class="panel settings-form">${settingsContent()}</section></div>`;}
function settingsContent(){if(state.settingsTab==='profile')return `<h2>My Profile</h2><p>Your personal details within ${esc(state.profile.company)}.</p><div class="profile-intro"><span class="avatar">${esc(initials(state.profile.name))}</span><div><strong>${esc(state.profile.name)}</strong><small>${esc(state.profile.role)} · ${esc(state.profile.company)}</small></div></div><form id="profile-form"><div class="form-grid"><label class="field">Full name<input name="name" value="${esc(state.profile.name)}" maxlength="80" required autocomplete="name"></label><label class="field">Email address<input name="email" type="email" value="${esc(state.profile.email)}" maxlength="254" required autocomplete="email"></label><label class="field">Country<select name="country">${['India','Singapore','United States','United Arab Emirates'].map(c=>`<option ${state.profile.country===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Time zone<select name="timezone">${['Asia/Kolkata','Asia/Singapore','America/New_York','Europe/London','UTC'].map(t=>`<option ${state.profile.timezone===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="form-actions">${btn('Save Changes','submit-form','','primary','type="submit"')}</div><p class="dialog-note">Profile changes apply to this demo session.</p></form>`;
if(state.settingsTab==='organisation')return `<h2>Organisation</h2><p>Your company details and workspace identity.</p><form id="organisation-form"><div class="form-grid"><label class="field full">Company name<input name="company" value="${esc(state.profile.company)}" maxlength="120" required autocomplete="organization"></label><label class="field">Country<select name="country">${['India','Singapore','United States','United Arab Emirates'].map(c=>`<option ${state.organisation.country===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Business type<select name="type">${['Private Limited Company','Limited Liability Partnership','Other registered business'].map(t=>`<option ${state.organisation.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field full">Registered address<textarea name="address" maxlength="300">${esc(state.organisation.address)}</textarea></label></div><div class="note-panel">${icon('shield')}<span>Verified business workspace · Sample company information.</span></div><div class="form-actions">${btn('Save Changes','submit-form','','primary','type="submit"')}</div></form>`;
if(state.settingsTab==='notifications')return `<h2>Notifications</h2><p>Choose what you want to stay informed about.</p><form id="preferences-form">${[['email','Email notifications','Receive workspace activity updates by email.'],['settlements','Settlement updates','Completion, delays and actions that need your attention.'],['availability','Available to settle','Changes to how much you can settle right now.'],['weekly','Weekly summary','An overview of your week of settlements.']].map(([id,title,desc])=>`<label class="switch-row"><span>${title}<small>${desc}</small></span><input class="switch" type="checkbox" name="${id}" ${state.preferences[id]?'checked':''}></label>`).join('')}<div class="form-actions">${btn('Save Preferences','submit-form','','primary','type="submit"')}</div><p class="dialog-note">Preferences are saved on this device. No emails are sent by the demo.</p></form>`;
return `<h2>Security</h2><p>Visibility and control over your workspace access.</p><div class="switch-row"><span>Two-factor authentication<small>Add an extra layer of protection to your account.</small></span>${status('Enabled')}</div><div class="switch-row"><span>Workspace role<small>Access to settlements, beneficiaries and team settings.</small></span><strong>Administrator</strong></div><div class="switch-row"><span>Current session<small>This browser · Demo workspace</small></span>${status('Active')}</div><div class="note-panel">${icon('info')}<span>This is an interactive product demo. Account security and authentication services are not connected.</span></div><div class="form-actions">${btn('View Access Details','access-details','shield')}</div>`;}

function initials(name){return name.trim().split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase();}
function routeFromHash(){const key=location.hash.replace(/^#\/?/,'').split('?')[0];return allRoutes.some(r=>r[0]===key)?key:'overview';}
function render(){closeSelects();state.route=routeFromHash();const renderer={overview,settlements,liquidity,beneficiaries,batches,reconciliation,developers,settings}[state.route];$('#main-nav').innerHTML=routes.map(([id,title,ico])=>`<a class="nav-link ${state.route===id?'active':''}" href="#/${id}" title="${title}" ${state.route===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-label">${title}</span></a>`).join('');$('#workspace').className=state.route+'-page screen-enter';$('#workspace').innerHTML=renderer();document.title=allRoutes.find(r=>r[0]===state.route)[1]+' · INRSettle';updateAccount();syncSelection();enhanceSelects($('#workspace'));}
function navigate(route){closeDialog();closeMenu();if(state.route===route){render();$('#workspace').focus({preventScroll:true});openSelectedDrawer();return;}location.hash='/'+route;}
function updateResults(){const el=$('#settlement-results');if(!el)return;const active=document.activeElement;let restore=null;if(active?.classList.contains('row-checkbox'))restore='.row-checkbox[data-id="'+active.dataset.id+'"]';else if(active?.id==='select-all')restore='#select-all';else if(active?.classList.contains('sort-button'))restore='.sort-button';el.innerHTML=settlementResults();syncSelection();if(restore)$(restore,el)?.focus({preventScroll:true});}
function updateAccount(){$('.account-copy strong').textContent=state.profile.name;$('.account-copy small').textContent=state.profile.company;$('.account-button .avatar').textContent=initials(state.profile.name);$('.account-button').setAttribute('aria-label',`Account menu for ${state.profile.name}`);}
const detailInDrawer=()=>window.matchMedia('(max-width:1559px)').matches;
function syncSelection(){
  const rows=filteredRows().slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);
  const checked=rows.filter(s=>state.checked.has(s.id)).length;
  const all=$('#select-all');
  if(all){all.indeterminate=checked>0&&checked<rows.length;all.setAttribute('aria-checked',all.indeterminate?'mixed':String(all.checked));}
}
function openSelectedDrawer(){
  if(!state.pendingDetail)return;
  const s=state.settlements.find(s=>s.id===state.pendingDetail);
  state.pendingDetail=null;
  if(s&&detailInDrawer())openDialog(`<h2 id="dialog-title" class="visually-hidden">${s.id} details</h2>${details(s)}`,'settlement-drawer');
}
function selectSettlement(id,fromOverview=false){
  const s=state.settlements.find(s=>s.id===id);if(!s)return;
  state.selected=id;
  if(fromOverview){
    state.filters={query:'',status:'',corridor:'',currency:'',start:'',end:''};state.checked.clear();
    state.page=pageForRecord(filteredRows(),id,PAGE_SIZE);state.pendingDetail=id;
    navigate('settlements');return;
  }
  closeDialog();updateResults();
  if($('#settlement-details')){$('#settlement-details').innerHTML=details(s);$('.settlements-layout').classList.remove('no-detail');}
  state.pendingDetail=id;openSelectedDrawer();
}
function rowActions(id){
  const s=state.settlements.find(s=>s.id===id);if(!s)return;
  openDialog(`<h2 id="dialog-title">${id}</h2><p class="dialog-description">${esc(s.name)} · ${s.from} → ${s.to}</p><div class="account-menu"><button data-action="open-settlement" data-id="${id}">${icon('wallet-cards')}View Settlement</button><button data-action="copy-id" data-id="${id}">${icon('copy')}Copy Settlement ID</button><button data-action="download-report" data-id="${id}">${icon('download')}Download Report</button><button data-action="create-similar" data-id="${id}">${icon('send')}Create Similar</button></div>`,'action-dialog');
}

let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function download(filename,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text,message='Copied to clipboard.'){try{await navigator.clipboard.writeText(text);toast(message);}catch{download('inrsettle-copy.txt',text);toast('Clipboard unavailable. Text downloaded instead.');}}
function openDialog(content,cls=''){closeSelects();closeMenu();const dialog=$('#app-dialog');dialog.className='dialog '+cls;$('#dialog-content').innerHTML=(['command-dialog','settlement-drawer'].includes(cls)?'':`<img class="dialog-brand" src="/assets/brand-wordmark.svg" width="934" height="95" alt="INRSettle">`)+content;if(!dialog.open)dialog.showModal();document.body.classList.add('dialog-open');enhanceSelects(dialog);const autofocus=$('[autofocus]',dialog);if(autofocus)requestAnimationFrame(()=>autofocus.focus());}
function closeDialog(){closeSelects();rememberWizard();const d=$('#app-dialog');if(d.open)d.close();document.body.classList.remove('dialog-open');}
function closeMenu(){document.body.classList.remove('navigation-open');$('#sidebar').classList.remove('open');$('.sidebar-scrim').hidden=true;$('.mobile-menu').setAttribute('aria-expanded','false');}
function openMenu(){document.body.classList.add('navigation-open');$('#sidebar').classList.add('open');$('.sidebar-scrim').hidden=false;$('.mobile-menu').setAttribute('aria-expanded','true');$('.sidebar-close').focus();}

function startWizard(source=null,preflight=false){
  const cp=state.beneficiaries.find(c=>c.name===source?.name)||state.beneficiaries[0];
  state.wizard={step:0,beneficiary:cp.id,from:source?.from||'INR',currency:source?.to||'USDC',amount:source?.send||2500000,reference:source?(source.reference+'-COPY').slice(0,50):'',preflight,createdId:null};
  renderWizard();
}
function quoteLabel(w){const q=routeQuote(w.amount,w.from,w.currency);if(!q)return 'Choose an available corridor';return w.from==='INR'?`1 ${w.currency} ≈ ${money(1/q.rate,'INR',2)}`:`1 ${w.from} ≈ ${money(q.rate,'INR',2)}`;}
function rememberWizard(changed=''){
  const form=$('#settlement-form');const w=state.wizard;if(!form||!w)return;
  w.beneficiary=form.elements.beneficiary.value;w.from=form.elements.from.value;
  let desired=form.elements.currency.value;
  if(changed==='beneficiary'){
    const cp=state.beneficiaries.find(c=>c.id===w.beneficiary);
    if(cp.currency==='INR'&&w.from==='INR')w.from='USDC';
    if(cp.currency!=='INR'&&w.from!=='INR')w.from='INR';
    form.elements.from.value=w.from;desired=cp.currency;
  }
  const choices=corridorOptions[w.from];
  w.currency=choices.includes(desired)?desired:choices[0];
  if(changed==='from'||changed==='beneficiary')form.elements.currency.innerHTML=choices.map(c=>`<option ${c===w.currency?'selected':''}>${c}</option>`).join('');
  w.reference=form.elements.reference.value;w.amount=Number(form.elements.amount.value);
  form.elements.amount.min=w.from==='INR'?'1000':'10';form.elements.amount.max=w.from==='INR'?'100000000':'1000000';
  form.elements.amount.setAttribute('aria-label',`Send amount in ${w.from}`);
  $('#send-symbol').textContent=currencySymbol(w.from);$('#send-currency-tag').innerHTML=coin(w.from)+w.from;
  const q=routeQuote(w.amount,w.from,w.currency);
  $('#receive-estimate').textContent=q?money(q.receive,w.currency,2)+' '+w.currency:'—';
  $('#quote-rate').textContent=quoteLabel(w);
  refreshSelect(form.elements.from);refreshSelect(form.elements.currency);refreshSelect(form.elements.beneficiary);
}
function renderWizard(){
  const w=state.wizard;const cp=state.beneficiaries.find(c=>c.id===w.beneficiary);
  const q=routeQuote(w.amount,w.from,w.currency);const estimate=q?.receive??0;let body='';
  if(w.step===0)body=`<form id="settlement-form"><div class="form-grid">
    <label class="field full">Beneficiary<select name="beneficiary" required>${state.beneficiaries.map(c=>`<option value="${c.id}" ${c.id===w.beneficiary?'selected':''}>${esc(c.name)} · ${esc(c.country)}</option>`).join('')}</select></label>
    <label class="field">Send currency<select name="from">${Object.keys(corridorOptions).map(c=>`<option ${c===w.from?'selected':''}>${c}</option>`).join('')}</select></label>
    <label class="field">Receive currency<select name="currency">${corridorOptions[w.from].map(c=>`<option ${c===w.currency?'selected':''}>${c}</option>`).join('')}</select></label>
    <label class="field full">Reference<input name="reference" value="${esc(w.reference)}" placeholder="e.g. INV-2024-0624" maxlength="50" required></label></div>
    <div class="amount-field"><label for="send-amount">You send</label><div class="amount-input-row"><span id="send-symbol">${currencySymbol(w.from)}</span><input id="send-amount" type="number" name="amount" min="${w.from==='INR'?1000:10}" max="${w.from==='INR'?100000000:1000000}" step="0.01" value="${w.amount}" aria-label="Send amount in ${w.from}" required><span class="currency-tag" id="send-currency-tag">${coin(w.from)}${w.from}</span></div></div>
    <div class="estimate-row"><span>Beneficiary receives approximately</span><strong id="receive-estimate">${money(estimate,w.currency,2)} ${w.currency}</strong></div><div class="quote-rate"><span>Illustrative exchange rate</span><span id="quote-rate">${quoteLabel(w)}</span></div>
    <div class="form-actions">${btn('Cancel','dialog-close','','','type="button"')}${btn('Run Preflight','submit-form','arrow','primary','type="submit"')}</div><p class="dialog-note">Product preview. No funds will be moved.</p></form>`;
  if(w.step===1){const verified=cp.status==='Verified';body=`<div class="preflight-summary ${verified?'':'review-required'}">${icon(verified?'check-circle':'info')}<div><strong>${verified?'Your route is ready.':'Beneficiary review required.'}</strong><p>${verified?'Review the details below before creating the settlement.':'Complete the beneficiary review to continue.'}</p></div></div>
    <ul class="preflight-checks"><li>${icon(verified?'check-circle':'info')}Beneficiary verification<span>${verified?'Cleared':'Review required'}</span></li><li>${icon('check-circle')}${w.from} → ${w.currency} corridor<span>Available</span></li><li>${icon('check-circle')}Available to settle<span>Sufficient</span></li><li>${icon('check-circle')}Estimated completion<span>&lt; 60 seconds</span></li></ul>
    <ul class="settlement-review"><li><span>Beneficiary</span><strong>${esc(cp.name)}</strong></li><li><span>You send</span><strong>${money(w.amount,w.from)}</strong></li><li><span>Beneficiary receives</span><strong>${money(estimate,w.currency,2)} ${w.currency}</strong></li><li><span>Reference</span><strong>${esc(w.reference)}</strong></li></ul>
    <div class="form-actions">${btn('Back','wizard-back','arrow-left')}${verified?btn('Create Settlement','wizard-confirm','check','primary'):btn('Review Beneficiary','review-beneficiary','user','primary',`data-name="${esc(cp.name)}"`)}</div><p class="dialog-note">Sample preflight and rate. No transfer is submitted.</p>`;}
  if(w.step===2)body=`<div class="success-state"><span class="metric-icon">${icon('check-circle')}</span><h3>Settlement created.</h3><p><strong>${w.createdId}</strong> is ready for review in your workspace.</p><div class="copy-box"><span>${w.createdId}</span><button class="small-button" data-action="copy-id" data-id="${w.createdId}">${icon('copy')}Copy ID</button></div><ul class="settlement-review"><li><span>Beneficiary</span><strong>${esc(cp.name)}</strong></li><li><span>Amount</span><strong>${money(w.amount,w.from)} → ${w.currency}</strong></li><li><span>Status</span><strong>${status('Ready')}</strong></li></ul><div class="form-actions">${btn('View Settlement','wizard-view','arrow','primary')}</div><p class="dialog-note">Created in this demo session. No money has been sent.</p></div>`;
  openDialog(`<h2 id="dialog-title">${w.step===2?'Ready for the next step.':w.preflight?'Run a Preflight':'Create Settlement'}</h2><p class="dialog-description">${w.step===2?'One complete record, from intent to settlement.':w.preflight?'Check the beneficiary, the route and what you can settle before you send.':'A single, connected flow from source to destination.'}</p>${w.step<2?`<div class="stepper" aria-label="Settlement creation progress">${['Settlement details','Preflight','Confirmation'].map((s,i)=>`<div class="${i<=w.step?'active':''}" ${i===w.step?'aria-current="step"':''}><span>${i<w.step?'✓':'0'+(i+1)}</span>${s}</div>`).join('')}</div>`:''}${body}`);
}
function commitDemoSettlement(){
  const w=state.wizard;if(!w||w.createdId)return;
  const cp=state.beneficiaries.find(c=>c.id===w.beneficiary);const quote=routeQuote(w.amount,w.from,w.currency);
  if(cp.status!=='Verified'||!quote)return;
  const last=Math.max(...state.settlements.map(s=>Number(s.id.split('-')[1])));w.createdId='STL-'+(last+1);
  state.settlements.unshift({id:w.createdId,date:'2024-06-24',time:'11:05',from:w.from,to:w.currency,name:cp.name,country:cp.country,send:w.amount,receive:quote.receive,status:'Ready',eta:'Awaiting approval',reference:w.reference});
  state.selected=w.createdId;state.filters={query:'',status:'',corridor:'',currency:'',start:'2024-06-01',end:'2024-06-30'};state.page=1;state.checked.clear();w.step=2;render();renderWizard();
}

function beneficiaryForm(){openDialog(`<h2 id="dialog-title">Add Beneficiary</h2><p class="dialog-description">Create a beneficiary in your demo workspace.</p><form id="beneficiary-form"><div class="form-grid"><label class="field full">Business name<input name="name" placeholder="Registered company name" maxlength="100" required autofocus></label><label class="field">Country<select name="country">${['United States','Singapore','Germany','United Arab Emirates','India','France','United Kingdom'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Receive currency<select name="currency">${['USDC','USDT','EURC','AED','INR'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field full">Contact email<input name="email" type="email" placeholder="finance@company.com" maxlength="254" required></label></div><div class="note-panel">${icon('shield')}<span>New beneficiaries start in review. Details stay in this demo session.</span></div><div class="form-actions">${btn('Cancel','dialog-close','','','type="button"')}${btn('Add Beneficiary','submit-form','user-plus','primary','type="submit"')}</div></form>`);}
function viewBeneficiary(id){const c=state.beneficiaries.find(c=>c.id===id);if(!c)return;const recent=state.settlements.filter(s=>s.name===c.name);openDialog(`<h2 id="dialog-title">Beneficiary Details</h2><div class="profile-intro"><span class="company-avatar large">${esc(initials(c.name))}</span><div><strong>${esc(c.name)}</strong><small>${c.id} · ${esc(c.country)}</small></div></div><ul class="key-value-list"><li><span>Verification</span>${status(c.status)}</li><li><span>Receive currency</span><strong>${coin(c.currency)} ${c.currency}</strong></li><li><span>Contact email</span><span>${esc(c.email)}</span></li><li><span>Settlements in workspace</span><strong>${recent.length}</strong></li></ul>${c.status!=='Verified'?`<div class="note-panel">${icon('info')}<span>Verification is pending. In this demo, you can preview a completed review.</span></div>`:''}<div class="form-actions">${btn('Copy Details','copy-beneficiary','copy','',`data-id="${c.id}"`)}${c.status==='Verified'?btn('Create Settlement','pay-beneficiary','send','primary',`data-id="${c.id}"`):btn('Preview Verified State','verify-beneficiary','shield','primary',`data-id="${c.id}"`)}</div>`);}
function showDateRange(){openDialog(`<h2 id="dialog-title">Settlement Period</h2><p class="dialog-description">Choose a date range for your settlement view.</p><div class="date-presets"><button data-action="date-preset" data-period="month">June 2024</button><button data-action="date-preset" data-period="week">Jun 18–24</button><button data-action="date-preset" data-period="all">All dates</button></div><form id="date-form"><div class="form-grid"><label class="field">From<input type="date" name="start" value="${state.filters.start}"></label><label class="field">To<input type="date" name="end" value="${state.filters.end}"></label></div><p class="form-error" id="date-error" role="alert"></p><div class="form-actions">${btn('Cancel','dialog-close','','','type="button"')}${btn('Apply Range','submit-form','check','primary','type="submit"')}</div></form>`);}
function showSearch(){openDialog(`<h2 id="dialog-title" class="visually-hidden">Search workspace</h2><div class="command-heading">${icon('search')}<input id="command-search" autocomplete="off" placeholder="Search your workspace…" aria-label="Search workspace" autofocus></div><div class="command-results" id="command-results">${commandResults('')}</div><p class="command-hint">↑ ↓ to navigate &nbsp;·&nbsp; Enter to open &nbsp;·&nbsp; Esc to close</p>`,'command-dialog');}
function commandResults(query){const q=query.toLowerCase().trim();const r=routes.filter(v=>v[1].toLowerCase().includes(q));const s=state.settlements.filter(s=>[s.id,s.name,s.from,s.to,s.reference].join(' ').toLowerCase().includes(q)).slice(0,5);const c=q?state.beneficiaries.filter(c=>[c.name,c.country].join(' ').toLowerCase().includes(q)).slice(0,3):[];let html='';if(r.length)html+=`<p class="command-label">Workspace</p>${r.map(([id,title,ico])=>`<button class="command-result" data-action="navigate" data-route="${id}">${icon(ico)}<strong>${title}</strong><span>Open ${icon('arrow')}</span></button>`).join('')}`;if(s.length)html+=`<p class="command-label">Settlements</p>${s.map(s=>`<button class="command-result" data-action="search-settlement" data-id="${s.id}">${icon('wallet-cards')}<span><strong>${s.id}</strong><small>${esc(s.name)} · ${s.from} → ${s.to}</small></span><span>${money(s.send,s.from)}</span></button>`).join('')}`;if(c.length)html+=`<p class="command-label">Beneficiaries</p>${c.map(c=>`<button class="command-result" data-action="beneficiary" data-id="${c.id}">${icon('users')}<span><strong>${esc(c.name)}</strong><small>${esc(c.country)}</small></span><span>${c.currency}</span></button>`).join('')}`;return html||`<div class="empty-state">${icon('search')}<strong>No results found</strong><p>Search a settlement ID, company, currency or workspace section.</p></div>`;}
function showNotifications(){openDialog(`<h2 id="dialog-title">Notifications</h2><p class="dialog-description">Your latest settlement activity.</p>${[['check-circle','Settlement completed','STL-784521 · ₹ 25,00,000 delivered to TechFlow Inc.','12 minutes ago'],['info','Beneficiary needs attention','Al Noor Trading is waiting for a verification review.','1 hour ago'],['check-circle','Available to settle updated','More is available to settle right now.','3 hours ago']].map(([ico,title,description,time])=>`<div class="notification-item"><span class="metric-icon">${icon(ico)}</span><div><strong>${title}</strong><p>${description}</p><small>${time}</small></div></div>`).join('')}<div class="form-actions">${btn('Mark All as Read','mark-read','check','primary')}</div>`);}
function showAccount(){openDialog(`<h2 id="dialog-title" class="visually-hidden">Your workspace</h2><div class="account-menu"><div class="profile-intro"><span class="avatar">${esc(initials(state.profile.name))}</span><div><strong>${esc(state.profile.name)}</strong><small>${esc(state.profile.email)}</small></div></div><button data-action="navigate" data-route="settings">${icon('user')}My Profile</button><button data-action="organisation">${icon('building')}${esc(state.profile.company)}</button><a href="/">${icon('arrow-left')}Back to INRSettle website</a></div><p class="dialog-note">Interactive demo workspace · Sample data</p>`);}
function showTrack(){openDialog(`<h2 id="dialog-title">Track Finality</h2><p class="dialog-description">Find a settlement and follow its complete timeline.</p><form id="track-form"><label class="field">Settlement ID<input name="id" placeholder="STL-784521" value="${state.selected||''}" list="settlement-ids" required autofocus maxlength="30"></label><datalist id="settlement-ids">${state.settlements.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</datalist><p class="form-error" id="track-error" role="alert"></p><div class="form-actions">${btn('Track Settlement','submit-form','activity','primary','type="submit"')}</div></form>`);}
function showTransaction(id){const s=state.settlements.find(s=>s.id===id);if(!s)return;openDialog(`<h2 id="dialog-title">Transaction Record</h2><p class="dialog-description">A unified view of the settlement’s execution and finality.</p><ul class="key-value-list"><li><span>Settlement</span><strong>${s.id}</strong></li><li><span>Network</span><strong>${settlementNetwork(s).name}</strong></li><li><span>Route</span><strong>${s.from} → ${s.to}</strong></li><li><span>Amount</span><strong>${money(s.receive,s.to)} ${s.to}</strong></li><li><span>Execution status</span>${status(s.status)}</li><li><span>Reference</span><strong>${esc(s.reference)}</strong></li></ul><div class="note-panel">${icon('info')}<span>This is a sample transaction. No blockchain transaction was broadcast and no external explorer record exists.</span></div><div class="form-actions">${btn('Download Record','download-report','download','primary',`data-id="${s.id}"`)}</div>`);}
function showCorridors(){openDialog(`<h2 id="dialog-title">Connected Corridors</h2><p class="dialog-description">Explore the routes featured in this workspace.</p><ul class="key-value-list">${[['USDC','United States · Multi-chain'],['USDT','Singapore · Multi-chain'],['EURC','Europe · Ethereum'],['AED','United Arab Emirates · Bank payout']].map(([currency,country])=>`<li><span>${pair({from:'INR',to:currency})}<small>${country}</small></span><button class="small-button" data-action="corridor-create" data-currency="${currency}">Create ${icon('arrow')}</button></li>`).join('')}</ul><p class="dialog-note">Sample routes and timing for this visual demo.</p>`);}
function showSupport(){openDialog(`<h2 id="dialog-title">How can we help?</h2><p class="dialog-description">Prepare a message for the INRSettle team.</p><form id="support-form"><div class="form-grid"><label class="field full">Topic<select name="topic"><option>Settlement assistance</option><option>Available to settle</option><option>Beneficiary verification</option><option>Integration support</option></select></label><label class="field full">Your message<textarea name="message" placeholder="Tell us what you need help with…" maxlength="2000" required autofocus></textarea></label></div><div class="form-actions">${btn('Download Support Brief','submit-form','download','primary','type="submit"')}</div><p class="dialog-note">Your brief downloads locally so you can share it with your team. It is not sent automatically.</p></form>`);}
function webhook(event='settlement.completed'){const payload={id:'evt_demo_0624',type:event,created_at:'2024-06-24T11:02:00Z',data:{settlement_id:'STL-784521',status:event.split('.')[1],source_currency:'INR',destination_currency:'USDC',reference:'TFI-2024-0624'},livemode:false};const json=JSON.stringify(payload,null,2);openDialog(`<h2 id="dialog-title">Webhook Payload</h2><p class="dialog-description">${esc(event)} · Sample event</p><pre class="code-block" style="margin:0"><code>${esc(json)}</code></pre><div class="form-actions">${btn('Copy JSON','copy-webhook','copy','primary',`data-event="${esc(event)}"`)}</div>`);return json;}
function report(s){return ['INRSettle · Demo settlement report','',`Settlement ID: ${s.id}`,`Created: ${displayDate(s.date)} ${s.time}`,`Beneficiary: ${s.name}`,`Country: ${s.country}`,`Reference: ${s.reference}`,`Corridor: ${s.from} → ${s.to}`,`Send amount: ${money(s.send,s.from)}`,`Receive amount: ${money(s.receive,s.to)}`,`Status: ${s.status}`,'','Illustrative product data. This document is not proof of payment.'].join('\n');}

document.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target){const row=event.target.closest('[data-row]');if(row&&!event.target.closest('input'))selectSettlement(row.dataset.row,state.route==='overview');return;}const action=target.dataset.action;if(target.closest('#main-nav')){closeMenu();return;}if(!action||action==='submit-form')return;if(target.tagName==='BUTTON'&&target.closest('form'))event.preventDefault();
  if(action==='navigate')return navigate(target.dataset.route);
  if(allRoutes.some(r=>r[0]===action))return navigate(action);
  if(action==='menu')return openMenu();
  if(action==='menu-close')return closeMenu();
  if(action==='dialog-close')return closeDialog();
  if(action==='search')return showSearch();
  if(action==='notifications')return showNotifications();
  if(action==='account')return showAccount();
  if(action==='support')return showSupport();
  if(action==='create')return startWizard();
  if(action==='preflight')return startWizard(null,true);
  if(action==='track')return showTrack();
  if(action==='corridors')return showCorridors();
  if(action==='add-beneficiary')return beneficiaryForm();
  if(action==='open-settlement'||action==='search-settlement'){closeDialog();if(action==='search-settlement'){state.filters={query:'',status:'',corridor:'',currency:'',start:'',end:''};state.page=1;}return selectSettlement(target.dataset.id,true);}
  if(action==='select-settlement')return selectSettlement(target.dataset.id);
  if(action==='row-actions')return rowActions(target.dataset.id);
  if(action==='clear-selection'){state.checked.clear();return updateResults();}
  if(action==='close-detail'){if($('#app-dialog').open)return closeDialog();state.selected=null;$('#settlement-details').innerHTML='';$('.settlements-layout').classList.add('no-detail');updateResults();return;}
  if(action==='sort'){state.sort=state.sort==='desc'?'asc':'desc';return updateResults();}
  if(action==='page-prev'){state.page=Math.max(1,state.page-1);return updateResults();}
  if(action==='page-next'){state.page++;return updateResults();}
  if(action==='page'){state.page=Number(target.dataset.page);return updateResults();}
  if(action==='clear-filters'){state.filters={query:'',status:'',corridor:'',currency:'',start:'',end:''};state.page=1;state.checked.clear();return render();}
  if(action==='review-attention'){state.filters={query:'',status:'Action required',corridor:'',currency:'',start:'',end:''};state.page=1;return navigate('settlements');}
  if(action==='import-batch')return openDialog(`<h2 id="dialog-title">Import a batch</h2><p class="dialog-description">A CSV of settlements, validated row by row. Rows that fail validation are listed back to you and the rest of the batch still goes ahead \u2014 an incomplete row never blocks a valid one.</p><p class="dialog-note">CSV import is not connected in this demo.</p><div class="form-actions">${btn('Close','dialog-close','','primary','type="button"')}</div>`);
  if(action==='date-range')return showDateRange();
  if(action==='date-preset'){const period=target.dataset.period;$('[name=start]',$('#date-form')).value=period==='month'?'2024-06-01':period==='week'?'2024-06-18':'';$('[name=end]',$('#date-form')).value=period==='month'?'2024-06-30':period==='week'?'2024-06-24':'';return;}
  if(action==='export'){const rows=state.checked.size?state.settlements.filter(s=>state.checked.has(s.id)):filteredRows();if(!rows.length)return toast('No settlements to export.');download('INRSettle-settlements-demo.csv',csv(rows),'text/csv;charset=utf-8');return toast(`${rows.length} settlement records exported.`);}
  if(action==='download-report'){const s=state.settlements.find(s=>s.id===target.dataset.id);if(s){download(s.id+'-demo-report.txt',report(s));toast('Settlement report downloaded.');}return;}
  if(action==='copy-id')return copy(target.dataset.id,'Settlement ID copied.');
  if(action==='create-similar')return startWizard(state.settlements.find(s=>s.id===target.dataset.id));
  if(action==='wizard-back'){state.wizard.step=0;return renderWizard();}
  if(action==='wizard-confirm')return commitDemoSettlement();
  if(action==='wizard-view')return selectSettlement(state.wizard.createdId,true);
  if(action==='transaction')return showTransaction(target.dataset.id);
  if(action==='beneficiary')return viewBeneficiary(target.dataset.id);
  if(action==='review-beneficiary'){rememberWizard();const c=state.beneficiaries.find(c=>c.name===target.dataset.name);if(c){if(state.wizard?.step===1&&state.wizard.beneficiary===c.id)state.wizard.resumeAfterReview=true;return viewBeneficiary(c.id);}return;}
  if(action==='copy-beneficiary'){const c=state.beneficiaries.find(c=>c.id===target.dataset.id);return copy(`${c.name}\n${c.country}\n${c.currency}\n${c.email}\n${c.id}`,'Beneficiary details copied.');}
  if(action==='pay-beneficiary'){const c=state.beneficiaries.find(c=>c.id===target.dataset.id);startWizard();state.wizard.beneficiary=c.id;state.wizard.from=c.currency==='INR'?'USDC':'INR';state.wizard.currency=c.currency;state.wizard.amount=c.currency==='INR'?25000:2500000;return renderWizard();}
  if(action==='verify-beneficiary'){const c=state.beneficiaries.find(c=>c.id===target.dataset.id);c.status='Verified';state.settlements.filter(s=>s.name===c.name&&s.status==='Action required').forEach(s=>{s.status='Ready';s.eta='Awaiting approval';});render();if(state.wizard?.resumeAfterReview&&state.wizard.beneficiary===c.id){state.wizard.resumeAfterReview=false;renderWizard();return toast('Beneficiary reviewed. Your settlement details are preserved.');}viewBeneficiary(c.id);return toast('Verified state enabled for this demo session.');}
  if(action==='export-beneficiaries'){const rows=[['ID','Name','Country','Currency','Verification','Email'],...state.beneficiaries.map(c=>[c.id,c.name,c.country,c.currency,c.status,c.email])];download('INRSettle-beneficiaries-demo.csv',rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');return toast('Beneficiary directory exported.');}
  if(action==='reconcile-tab'){state.reconcileTab=target.dataset.tab;render();requestAnimationFrame(()=>$(`#tab-${state.reconcileTab}`).focus());return;}
  if(action==='reports'){state.reconcileTab='reports';return navigate('reconciliation');}
  if(action==='reconciliation-report'){download('INRSettle-reconciliation-demo.csv',csv(state.settlements.filter(s=>s.status==='Settled')),'text/csv;charset=utf-8');return toast('Reconciliation report downloaded.');}
  if(action==='all-settlements-report'){download('INRSettle-monthly-summary-demo.csv',csv(state.settlements),'text/csv;charset=utf-8');return toast('Monthly settlement summary downloaded.');}
  if(action==='audit-report'){const events=state.settlements.flatMap(s=>settlementTimeline(s).filter(e=>e.at).map(e=>[s.id,e.at,e.title,e.phase,e.note]));events.sort((a,b)=>b[1].localeCompare(a[1]));download('INRSettle-audit-trail-demo.csv',csvRows(['Settlement ID','Timestamp','Event','State','Details'],events),'text/csv;charset=utf-8');return toast('Audit trail exported.');}
  if(action==='liquidity-report'){download('INRSettle-treasury-demo.csv','Asset,USD Equivalent,Allocation,Network\r\n'+balances.map(b=>`${b.currency},${b.amount},${b.share}%,${b.network}`).join('\r\n'),'text/csv;charset=utf-8');return toast('Treasury report downloaded.');}
  if(action==='add-liquidity'||action==='rebalance')return liquidityForm(action);
  if(action==='treasury-rules')return showTreasuryRules();
  if(action==='chart-day'){$$('.balance-bar').forEach(b=>b.classList.toggle('active',b===target));return;}
  if(action==='settings-tab'){state.settingsTab=target.dataset.tab;return render();}
  if(action==='organisation'){state.settingsTab='organisation';return navigate('settings');}
  if(action==='copy-api')return copy(apiExample,'Integration example copied.');
  if(action==='webhook')return webhook(target.dataset.event||'settlement.completed');
  if(action==='copy-webhook'){const json=webhook(target.dataset.event);return copy(json,'Webhook payload copied.');}
  if(action==='mark-read'){state.notificationsRead=true;$('.notification-button i').hidden=true;$('.notification-button').setAttribute('aria-label','Notifications, all read');closeDialog();return toast('All notifications marked as read.');}
  if(action==='corridor-create'){startWizard();state.wizard.currency=target.dataset.currency;return renderWizard();}
  if(action==='system-status')return openDialog(`<h2 id="dialog-title">Workspace Status</h2><p class="dialog-description">System status as shown in the sample workspace.</p><ul class="key-value-list">${['Settlement engine','Settlement routing','Compliance checks','Settlement records'].map(v=>`<li><span>${v}</span>${status('Operational')}</li>`).join('')}</ul><p class="dialog-note">Illustrative status. Live services are not monitored by this demo.</p>`);
  if(action==='access-details')return openDialog(`<h2 id="dialog-title">Workspace Access</h2><p class="dialog-description">${esc(state.profile.name)} · Administrator</p><ul class="key-value-list">${['Create and view settlements','See what you can settle','Review beneficiaries','View settlement receipts','Manage workspace settings'].map(v=>`<li><span>${v}</span>${icon('check-circle')}</li>`).join('')}</ul><p class="dialog-note">Illustrative permissions for this visual demo.</p>`);
});

document.addEventListener('input',event=>{const el=event.target;if(el.id==='settlement-search'){state.filters.query=el.value;state.page=1;state.checked.clear();updateResults();}if(el.id==='beneficiary-search'){state.cpQuery=el.value;$('#beneficiary-results').innerHTML=beneficiaryResults();}if(el.id==='command-search')$('#command-results').innerHTML=commandResults(el.value);if(el.closest('#settlement-form'))rememberWizard(el.name);});
document.addEventListener('change',event=>{const el=event.target;if(el.closest('#settlement-form'))rememberWizard(el.name);const filterKeys={'status-filter':'status','corridor-filter':'corridor','currency-filter':'currency'};if(filterKeys[el.id]){state.filters[filterKeys[el.id]]=el.value;state.page=1;state.checked.clear();return updateResults();}if(el.classList.contains('row-checkbox')){if(el.checked)state.checked.add(el.dataset.id);else state.checked.delete(el.dataset.id);updateResults();return;}if(el.id==='select-all'){const rows=filteredRows().slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);rows.forEach(s=>el.checked?state.checked.add(s.id):state.checked.delete(s.id));updateResults();return;}if(el.dataset.preference==='topup'){state.treasury.auto=el.checked;toast(el.checked?'Automatic top-up enabled in demo.':'Automatic top-up paused in demo.');}});

document.addEventListener('submit',event=>{const form=event.target;if(!form.id)return;event.preventDefault();for(const input of $$('input[required],textarea[required]',form)){if(['text','email','textarea'].includes(input.type)&&!input.value.trim()){input.setCustomValidity('Please enter a value.');input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});}}if(!form.reportValidity())return;const data=new FormData(form);
  if(form.id==='settlement-form'){rememberWizard();const w=state.wizard;w.reference=data.get('reference').trim();if(!w.reference){form.elements.reference.setCustomValidity('Enter a reference.');form.elements.reference.reportValidity();form.elements.reference.addEventListener('input',()=>form.elements.reference.setCustomValidity(''),{once:true});return;}w.step=1;return renderWizard();}
  if(form.id==='beneficiary-form'){const name=data.get('name').trim();if(!name)return;const id='BEN-'+(1001+state.beneficiaries.length);state.beneficiaries.push({id,name,country:data.get('country'),currency:data.get('currency'),email:data.get('email').trim(),status:'Needs review'});closeDialog();render();toast(`${name} added to your demo network.`);return viewBeneficiary(id);}
  if(form.id==='date-form'){const start=data.get('start'),end=data.get('end');if(start&&end&&start>end){$('#date-error').textContent='The end date must be on or after the start date.';return;}state.filters.start=start;state.filters.end=end;state.page=1;state.checked.clear();closeDialog();return render();}
  if(form.id==='track-form'){const id=data.get('id').trim().toUpperCase();const s=state.settlements.find(s=>s.id===id);if(!s){$('#track-error').textContent='We could not find this settlement. Try one of the sample IDs.';return;}closeDialog();return selectSettlement(id,true);}
  if(form.id==='liquidity-form'){const mode=form.dataset.mode;const asset=data.get('asset');const destination=data.get('destination');const amount=Number(data.get('amount'));const available=balances.find(b=>b.currency===asset).amount;if(mode==='rebalance'&&asset===destination){$('#liquidity-error').textContent='Choose a different destination asset.';return;}if(mode==='rebalance'&&amount>available){$('#liquidity-error').textContent='The amount exceeds the available source balance.';return;}return openDialog(`<h2 id="dialog-title">Allocation Preview</h2><p class="dialog-description">Review your proposed treasury allocation.</p><ul class="key-value-list"><li><span>Operation</span><strong>${mode==='rebalance'?'Rebalance':'Replenishment'}</strong></li><li><span>Asset</span><strong>${asset}</strong></li><li><span>${mode==='rebalance'?'Destination':'Funding source'}</span><strong>${esc(destination)}</strong></li><li><span>USD equivalent</span><strong>${money(amount,'USD',2)}</strong></li><li><span>Estimated availability</span><strong>3–6 hours</strong></li></ul><div class="note-panel">${icon('info')}<span>Preview complete. No funds have been moved or reserved.</span></div><div class="form-actions">${btn('Done','dialog-close','check','primary')}</div>`);}
  if(form.id==='treasury-form'){if(Number(data.get('target'))<Number(data.get('reserve'))){$('#treasury-error').textContent='The replenishment target must be at least the minimum reserve.';return;}state.treasury={reserve:Number(data.get('reserve')),target:Number(data.get('target')),auto:data.has('auto')};closeDialog();render();return toast('Treasury rules saved for this demo session.');}
  if(form.id==='profile-form'){state.profile={...state.profile,name:data.get('name').trim(),email:data.get('email').trim(),country:data.get('country'),timezone:data.get('timezone')};render();return toast('Profile updated for this demo session.');}
  if(form.id==='organisation-form'){state.profile.company=data.get('company').trim();state.organisation={country:data.get('country'),type:data.get('type'),address:data.get('address').trim()};render();return toast('Organisation details updated for this demo session.');}
  if(form.id==='preferences-form'){Object.keys(state.preferences).forEach(k=>state.preferences[k]=data.has(k));try{localStorage.setItem('inrsettle-demo-notifications',JSON.stringify(state.preferences));toast('Notification preferences saved on this device.');}catch{toast('Preferences applied for this session. Device storage is unavailable.');}return;}
  if(form.id==='support-form'){download('INRSettle-support-brief.txt',`INRSettle · Support brief\n\nFrom: ${state.profile.name}\nCompany: ${state.profile.company}\nTopic: ${data.get('topic')}\n\n${data.get('message').trim()}`);closeDialog();return toast('Support brief downloaded. Share it with your INRSettle contact.');}
});

document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();return showSearch();}if(event.key==='Escape'){if($('#sidebar').classList.contains('open')){closeMenu();$('.mobile-menu').focus();}return;}if($('#app-dialog').open&&$('#app-dialog').classList.contains('command-dialog')){const results=$$('.command-result',$('#command-results'));const active=results.indexOf(document.activeElement);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const index=event.key==='ArrowDown'?(active+1)%results.length:(active<=0?results.length-1:active-1);results[index]?.focus();}if(event.key==='Enter'&&event.target.id==='command-search'){event.preventDefault();results[0]?.click();}return;}const tab=event.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('[role=tab]',tab.parentElement);let i=tabs.indexOf(tab);i=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click();}if(event.key==='Tab'&&$('#sidebar').classList.contains('open')){const items=$$('a,button',$('#sidebar')).filter(el=>!el.disabled);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
$('#app-dialog').addEventListener('close',()=>{closeSelects();rememberWizard();document.body.classList.remove('dialog-open');if(document.activeElement===document.body)$('#workspace').focus({preventScroll:true});});
$('#app-dialog').addEventListener('click',event=>{if(event.target===$('#app-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#workspace').focus({preventScroll:true});openSelectedDrawer();});
window.matchMedia('(min-width:561px)').addEventListener('change',e=>{if(e.matches)closeMenu();});
try{const prefs=JSON.parse(localStorage.getItem('inrsettle-demo-notifications')||'null');if(prefs&&typeof prefs==='object')Object.keys(state.preferences).forEach(k=>{if(typeof prefs[k]==='boolean')state.preferences[k]=prefs[k];});}catch{}
$$('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon));
$('.sidebar-close').innerHTML=icon('x');
render();
